import itertools
import random
from solution import minPath

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---------- reference model (obviously correct brute force) ----------

def _pos_map(grid):
    pos = {}
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            pos[v] = (i, j)
    return pos


def _neighbors(cell, n):
    i, j = cell
    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        ni, nj = i + di, j + dj
        if 0 <= ni < n and 0 <= nj < n:
            yield (ni, nj)


def brute_min_path(grid, k):
    n = len(grid)
    # enumerate all paths of exactly k cells (revisits allowed)
    best = None
    # start from every cell
    # iterative expansion of value-lists + positions
    # each entry: (values_list, current_cell)
    cur = []
    for i in range(n):
        for j in range(n):
            cur.append(( [grid[i][j]], (i, j) ))
    if k == 1:
        return min(v for v, _ in cur)
    for step in range(2, k + 1):
        nxt = []
        for vals, cell in cur:
            for nb in _neighbors(cell, n):
                nxt.append((vals + [grid[nb[0]][nb[1]]], nb))
        cur = nxt
    best = min(v for v, _ in cur)
    return best


def min_neighbor_of_one(grid):
    n = len(grid)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                x, y = i, j
                break
    vals = []
    for nb in _neighbors((x, y), n):
        vals.append(grid[nb[0]][nb[1]])
    return min(vals)


def assert_valid_path(grid, k, path):
    n = len(grid)
    assert isinstance(path, list), "must return list"
    assert len(path) == k, "length must be k"
    pos = _pos_map(grid)
    for v in path:
        assert v in pos, "values must be from grid"
    for a, b in zip(path, path[1:]):
        ca = pos[a]
        cb = pos[b]
        assert cb in set(_neighbors(ca, n)), "consecutive values must be edge-adjacent cells"


# ---------- strategies ----------

def grid_strategy(n_min=2, n_max=3):
    def make_grid(n):
        vals = list(range(1, n * n + 1))
        return st.builds(
            lambda perm: [list(perm[i * n:(i + 1) * n]) for i in range(n)],
            st.permutations(vals),
        )
    return st.integers(n_min, n_max).flatmap(make_grid)


small_grid_and_k = st.tuples(grid_strategy(2, 3), st.integers(1, 5))
tiny_grid_and_k = st.tuples(grid_strategy(2, 2), st.integers(1, 4))


# ---------- spec examples ----------

def test_spec_example_1():
    assert minPath([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 3) == [1, 2, 1]


def test_spec_example_2():
    assert minPath([[5, 9, 3], [4, 1, 6], [7, 8, 2]], 1) == [1]


# ---------- properties ----------

@given(small_grid_and_k)
def test_property_length_equals_k(pair):
    grid, k = pair
    assert len(minPath(grid, k)) == k


@given(small_grid_and_k)
def test_property_path_is_valid_walk(pair):
    grid, k = pair
    path = minPath(grid, k)
    assert_valid_path(grid, k, path)


@given(small_grid_and_k)
def test_property_first_element_is_global_min(pair):
    # lexicographically minimal path must start at value 1
    grid, k = pair
    path = minPath(grid, k)
    assert path[0] == 1


@given(small_grid_and_k)
def test_property_equivalence_to_brute_force(pair):
    grid, k = pair
    assert minPath(grid, k) == brute_min_path(grid, k)


@given(small_grid_and_k)
def test_property_lexicographically_minimal(pair):
    grid, k = pair
    path = minPath(grid, k)
    # path must be <= every other feasible path of length k
    n = len(grid)
    pos = _pos_map(grid)
    # sample a few random feasible walks and check minimality
    rng = random.Random((tuple(tuple(r) for r in grid), k))
    for _ in range(20):
        i = rng.randrange(n)
        j = rng.randrange(n)
        walk = [grid[i][j]]
        ci, cj = i, j
        for _ in range(k - 1):
            nbs = list(_neighbors((ci, cj), n))
            ci, cj = rng.choice(nbs)
            walk.append(grid[ci][cj])
        assert path <= walk


@given(grid_strategy(2, 3))
def test_property_k1_is_singleton_one(grid):
    assert minPath(grid, 1) == [1]


@given(grid_strategy(2, 3))
def test_property_k2_is_one_plus_min_neighbor(grid):
    grid = grid
    assert minPath(grid, 2) == [1, min_neighbor_of_one(grid)]


@given(small_grid_and_k)
def test_property_alternation_of_one_and_min_neighbor(pair):
    # Theorem from spec: values are unique so value determines cell;
    # greedy lexicographic minimization forces oscillation between
    # cell 1 and its smallest neighbor.
    grid, k = pair
    mn = min_neighbor_of_one(grid)
    expected = [1 if i % 2 == 0 else mn for i in range(k)]
    assert minPath(grid, k) == expected


@given(tiny_grid_and_k)
def test_property_second_element_is_min_neighbor_of_one(pair):
    grid, k = pair
    assume(k >= 2)
    path = minPath(grid, k)
    assert path[1] == min_neighbor_of_one(grid)


def test_exhaustive_all_2x2_k_up_to_4():
    # exhaustive over all 2x2 permutation grids
    for perm in itertools.permutations([1, 2, 3, 4]):
        grid = [list(perm[0:2]), list(perm[2:4])]
        for k in (1, 2, 3, 4):
            assert minPath(grid, k) == brute_min_path(grid, k), f"{grid} k={k}"
            assert_valid_path(grid, k, minPath(grid, k))


def test_explicit_oscillation_needed():
    # 1 in corner: must bounce between 1 and smallest neighbor
    grid = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert minPath(grid, 4) == [1, 2, 1, 2]
    assert minPath(grid, 5) == [1, 2, 1, 2, 1]


def test_explicit_1_in_center():
    grid = [[5, 9, 3], [4, 1, 6], [7, 8, 2]]
    # neighbors of 1: 9,4,6,8 -> min is 4
    assert min_neighbor_of_one(grid) == 4
    assert minPath(grid, 2) == [1, 4]
    assert minPath(grid, 3) == [1, 4, 1]
    assert minPath(grid, 1) == [1]


def test_explicit_1_in_corner_larger_k():
    grid = [[2, 3, 4], [5, 6, 7], [8, 9, 1]]
    # neighbors of 1: 7,9 -> min 7
    assert minPath(grid, 3) == [1, 7, 1]
    assert minPath(grid, 6) == [1, 7, 1, 7, 1, 7]


def test_explicit_must_revisit_cells():
    # path length exceeds number of cells; revisits required
    grid = [[1, 2], [3, 4]]
    # neighbors of 1: 2,3 -> min 2
    assert minPath(grid, 5) == [1, 2, 1, 2, 1]
    assert_valid_path(grid, 5, minPath(grid, 5))
